std::vector<int> A = {10, 20, 30, 40, 50};
std::vector<int> B = {20, 25, 30, 35, 40};
std::vector<int> R;

// Inputs MUST be sorted ranges.

// Calculate intersection, appending results to R
std::set_intersection(
    A.begin(), A.end(),
    B.begin(), B.end(),
    std::back_inserter(R)
);

// R contains: {20, 30, 40}
// O(N + M) complexity.
// Can use std::ostream_iterator if printing immediately.
// Example: std::ostream_iterator<int>(std::cout, " ")
// Output is also sorted.
